#!/usr/bin/env python3

from __future__ import annotations

import calendar
import curses
import datetime as dt
import hashlib
import locale
import os
import re
import shlex
import shutil
import subprocess
import sys
from collections import Counter, defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Sequence, Tuple


VERSION = "commit-93cc85d16ab60ba8d646458fe0233778317b22a3"
DEFAULT_LOG_NAME_FORMAT = "y%Y/d%Y_%m_%d.md"
DEFAULT_LOG_DIR_NAME = ".caps-log/day"
DEFAULT_CONFIG_NAME = ".caps-log/config.ini"
ROOT_SECTION = "<root section>"

HELP_TEMPLATE = """Captain's Log (caps-log)! A CLI journalig tool.
Version: {version}
Allowed options:
  -h [ --help ]         show this message
  -c [ --config ] arg   override the default config file path
                        ({config_path})
  --log-dir-path arg    path where log files are stored
  --log-name-format arg format in which log entry markdown files are saved
  --sunday-start        have the calendar display sunday as first day of the
                        week
  --first-line-section  override the default behaviour of ignoring sections
                        (lines starting with `#`) in the first line of a log
                        entry file
  --password arg        password for encrypted log repositories or to be used
                        with --encrypt/--decrypt
  --encrypt             apply encryption to all logs in log dir path (needs
                        --password)
  --decrypt             apply decryption to all logs in log dir path (needs
                        --password)
"""


class CapsLogError(Exception):
    pass


@dataclass
class ParsedArgs:
    help: bool = False
    config_path: Optional[str] = None
    log_dir_path: Optional[str] = None
    log_name_format: Optional[str] = None
    sunday_start: bool = False
    first_line_section: bool = False
    password: Optional[str] = None
    encrypt: bool = False
    decrypt: bool = False


@dataclass
class AnnualEvent:
    group: str
    name: str
    month: int
    day: int


@dataclass
class Settings:
    config_path: Path
    log_dir: Path
    log_name_format: str
    sunday_start: bool
    first_line_section: bool
    password: Optional[str]
    encrypt: bool
    decrypt: bool
    recent_events_window: int = 60
    annual_events: List[AnnualEvent] = field(default_factory=list)


@dataclass
class LogEntry:
    date: dt.date
    path: Path
    content: str
    section_names: List[str]
    tags: List[Tuple[str, str]]


@dataclass
class PromptModal:
    kind: str
    title: str
    buffer: str = ""
    hidden: bool = False
    choice: int = 0


def default_config_path() -> Path:
    return Path.home() / DEFAULT_CONFIG_NAME


def default_log_dir() -> Path:
    return Path.home() / DEFAULT_LOG_DIR_NAME


def format_error(message: str) -> str:
    return f"Captain's log encountered an error: \n {message}\n"


def normalize_name(value: str) -> str:
    return " ".join(value.strip().lower().split())


def normalize_tag(value: str) -> str:
    text = value.strip()
    if not text:
        return ""
    for marker in ("(", ":"):
        pos = text.find(marker)
        if pos != -1:
            text = text[:pos]
    return normalize_name(text)


def strip_inline_comment(value: str) -> str:
    if value.startswith("#"):
        return value
    for marker in (" #", " ;"):
        pos = value.find(marker)
        if pos != -1:
            return value[:pos].rstrip()
    return value.rstrip()


def parse_bool(value: str) -> bool:
    return value.strip().lower() in {"1", "true", "yes", "on"}


def expand_path(value: Optional[str]) -> Optional[Path]:
    if value is None:
        return None
    return Path(os.path.expanduser(value))


def parse_args(argv: Sequence[str]) -> ParsedArgs:
    args = ParsedArgs()
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg in ("-h", "--help"):
            args.help = True
            i += 1
            continue
        if arg in ("-c", "--config"):
            i += 1
            if i >= len(argv):
                raise CapsLogError("the required argument for option '--config' is missing")
            args.config_path = argv[i]
            i += 1
            continue
        if arg.startswith("--config="):
            args.config_path = arg.split("=", 1)[1]
            i += 1
            continue
        if arg == "--log-dir-path":
            i += 1
            if i >= len(argv):
                raise CapsLogError("the required argument for option '--log-dir-path' is missing")
            args.log_dir_path = argv[i]
            i += 1
            continue
        if arg.startswith("--log-dir-path="):
            args.log_dir_path = arg.split("=", 1)[1]
            i += 1
            continue
        if arg == "--log-name-format":
            i += 1
            if i >= len(argv):
                raise CapsLogError("the required argument for option '--log-name-format' is missing")
            args.log_name_format = argv[i]
            i += 1
            continue
        if arg.startswith("--log-name-format="):
            args.log_name_format = arg.split("=", 1)[1]
            i += 1
            continue
        if arg == "--password":
            i += 1
            if i >= len(argv):
                raise CapsLogError("the required argument for option '--password' is missing")
            args.password = argv[i]
            i += 1
            continue
        if arg.startswith("--password="):
            args.password = arg.split("=", 1)[1]
            i += 1
            continue
        if arg == "--sunday-start":
            args.sunday_start = True
            i += 1
            continue
        if arg == "--first-line-section":
            args.first_line_section = True
            i += 1
            continue
        if arg == "--encrypt":
            args.encrypt = True
            i += 1
            continue
        if arg == "--decrypt":
            args.decrypt = True
            i += 1
            continue
        if arg.startswith("-"):
            raise CapsLogError(f"unrecognised option '{arg}'")
        raise CapsLogError("too many positional options have been specified on the command line")
    return args


def parse_config(path: Path) -> Tuple[Dict[str, str], Dict[str, Dict[str, str]]]:
    try:
        raw_lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        raise CapsLogError(f"Failed to open file: {path}")

    top_level: Dict[str, str] = {}
    sections: Dict[str, Dict[str, str]] = defaultdict(dict)
    current_section: Optional[str] = None

    for raw_line in raw_lines:
        line = raw_line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            current_section = line[1:-1].strip()
            continue
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip()
        value = strip_inline_comment(value.strip())
        if current_section:
            sections[current_section][key] = value
        else:
            top_level[key] = value
    return top_level, sections


def parse_annual_events(sections: Dict[str, Dict[str, str]]) -> Tuple[int, List[AnnualEvent]]:
    recent_events_window = 60
    if "calendar-events" in sections and "recent-events-window" in sections["calendar-events"]:
        try:
            recent_events_window = int(sections["calendar-events"]["recent-events-window"])
        except ValueError:
            recent_events_window = 60

    events: List[AnnualEvent] = []
    for section_name, values in sections.items():
        if not section_name.startswith("calendar-events."):
            continue
        parts = section_name.split(".")
        if len(parts) < 3:
            continue
        group = parts[1]
        name = values.get("name", "").strip()
        date_value = values.get("date", "").strip()
        match = re.match(r"^\s*(\d{1,2})\.(\d{1,2})\.?\s*$", date_value)
        if not name or not match:
            continue
        day = int(match.group(1))
        month = int(match.group(2))
        if not 1 <= month <= 12:
            continue
        if not 1 <= day <= 31:
            continue
        display_group = group.replace("birthadays", "birthdays")
        events.append(AnnualEvent(group=display_group, name=name, month=month, day=day))
    events.sort(key=lambda item: (item.group.lower(), item.month, item.day, item.name.lower()))
    return recent_events_window, events


def merge_settings(cli: ParsedArgs) -> Settings:
    config_path = expand_path(cli.config_path) or default_config_path()
    top_level, sections = parse_config(config_path)

    log_dir = expand_path(cli.log_dir_path) or expand_path(top_level.get("log-dir-path")) or default_log_dir()
    log_name_format = cli.log_name_format or top_level.get("log-name-format") or top_level.get("log-filename-format") or DEFAULT_LOG_NAME_FORMAT
    sunday_start = cli.sunday_start or parse_bool(top_level.get("sunday-start", "false"))
    first_line_section = cli.first_line_section or parse_bool(top_level.get("first-line-section", "false"))
    password = cli.password if cli.password is not None else top_level.get("password")
    recent_events_window, annual_events = parse_annual_events(sections)
    return Settings(
        config_path=config_path,
        log_dir=log_dir,
        log_name_format=log_name_format,
        sunday_start=sunday_start,
        first_line_section=first_line_section,
        password=password,
        encrypt=cli.encrypt,
        decrypt=cli.decrypt,
        recent_events_window=recent_events_window,
        annual_events=annual_events,
    )


@dataclass
class DatePattern:
    regex: re.Pattern[str]
    groups: List[Tuple[str, str]]


def build_date_pattern(fmt: str) -> DatePattern:
    parts: List[str] = ["^"]
    groups: List[Tuple[str, str]] = []
    counters = Counter()
    i = 0
    while i < len(fmt):
        char = fmt[i]
        if char != "%":
            parts.append(re.escape(char))
            i += 1
            continue
        i += 1
        if i >= len(fmt):
            parts.append(re.escape("%"))
            break
        token = fmt[i]
        i += 1
        counters[token] += 1
        group_name = f"{token}{counters[token]}"
        if token == "Y":
            parts.append(f"(?P<{group_name}>\\d{{4}})")
            groups.append((group_name, "Y"))
        elif token == "y":
            parts.append(f"(?P<{group_name}>\\d{{2}})")
            groups.append((group_name, "y"))
        elif token == "m":
            parts.append(f"(?P<{group_name}>\\d{{2}})")
            groups.append((group_name, "m"))
        elif token == "d":
            parts.append(f"(?P<{group_name}>\\d{{2}})")
            groups.append((group_name, "d"))
        else:
            parts.append(re.escape("%" + token))
    parts.append("$")
    return DatePattern(regex=re.compile("".join(parts)), groups=groups)


def match_date(pattern: DatePattern, rel_path: str) -> Optional[dt.date]:
    match = pattern.regex.match(rel_path)
    if not match:
        return None

    year: Optional[int] = None
    month: Optional[int] = None
    day: Optional[int] = None
    for group_name, kind in pattern.groups:
        value = int(match.group(group_name))
        if kind == "Y":
            parsed = value
            if year is None:
                year = parsed
            elif year != parsed:
                return None
        elif kind == "y":
            parsed = 1900 + value if value >= 69 else 2000 + value
            if year is None:
                year = parsed
            elif year != parsed:
                return None
        elif kind == "m":
            if month is None:
                month = value
            elif month != value:
                return None
        elif kind == "d":
            if day is None:
                day = value
            elif day != value:
                return None

    if year is None or month is None or day is None:
        return None

    try:
        return dt.date(year, month, day)
    except ValueError:
        return None


def parse_log_content(content: str, first_line_section: bool) -> Tuple[List[str], List[Tuple[str, str]]]:
    section_names: List[str] = []
    tags: List[Tuple[str, str]] = []
    current_section = ROOT_SECTION
    root_needed = False
    lines = content.splitlines()
    for idx, line in enumerate(lines):
        if line.startswith("# "):
            if idx == 0 and not first_line_section:
                continue
            current_section = normalize_name(line[2:])
            if current_section:
                if current_section not in section_names:
                    section_names.append(current_section)
            continue
        if line.startswith("* "):
            tag = normalize_tag(line[2:])
            if tag:
                tags.append((current_section, tag))
                if current_section == ROOT_SECTION:
                    root_needed = True
            continue
        if current_section == ROOT_SECTION and line.strip():
            root_needed = True

    if root_needed and ROOT_SECTION not in section_names:
        section_names.insert(0, ROOT_SECTION)
    return section_names, tags


def marker_bytes(password: str) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), b"caps-log-marker", 2048, 18)


def marker_path(log_dir: Path) -> Path:
    return log_dir / ".cle"


def read_marker(log_dir: Path) -> Optional[bytes]:
    path = marker_path(log_dir)
    try:
        return path.read_bytes()
    except FileNotFoundError:
        return None


def validate_password(log_dir: Path, password: str) -> bool:
    stored = read_marker(log_dir)
    if stored is None:
        return False
    return stored == marker_bytes(password)


def apply_encrypt(settings: Settings) -> int:
    if not settings.password:
        raise CapsLogError("Password must be provided when encrypting logs!")
    print("Applying crypto...")
    if marker_path(settings.log_dir).exists():
        raise CapsLogError("Already applied")
    if not settings.log_dir.exists():
        raise CapsLogError(
            f"filesystem error: directory iterator cannot open directory: No such file or directory [{settings.log_dir}]"
        )
    marker_path(settings.log_dir).write_bytes(marker_bytes(settings.password))
    return 0


def apply_decrypt(settings: Settings) -> int:
    if not settings.password:
        raise CapsLogError("Password must be provided when decrypting logs!")
    print("Applying crypto...")
    path = marker_path(settings.log_dir)
    if not path.exists():
        raise CapsLogError("Already applied")
    path.unlink()
    return 0


def list_scratchpads(log_dir: Path) -> List[str]:
    scratch_dir = log_dir / "scratchpads"
    if not scratch_dir.exists():
        return []
    names: List[str] = []
    for path in scratch_dir.glob("*.md"):
        if path.is_file():
            names.append(path.stem)
    return sorted(names, key=lambda item: item.lower())


def load_entries(log_dir: Path, log_name_format: str, first_line_section: bool) -> Dict[dt.date, LogEntry]:
    pattern = build_date_pattern(log_name_format)
    entries: Dict[dt.date, LogEntry] = {}
    if not log_dir.exists():
        return entries
    for path in sorted(log_dir.rglob("*")):
        if not path.is_file():
            continue
        if path.name == ".cle":
            continue
        try:
            rel = path.relative_to(log_dir).as_posix()
        except ValueError:
            continue
        if rel.startswith("scratchpads/"):
            continue
        parsed_date = match_date(pattern, rel)
        if parsed_date is None:
            continue
        try:
            content = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            content = path.read_text(encoding="utf-8", errors="replace")
        section_names, tags = parse_log_content(content, first_line_section)
        entries[parsed_date] = LogEntry(
            date=parsed_date,
            path=path,
            content=content,
            section_names=section_names,
            tags=tags,
        )
    return entries


def format_log_path(log_dir: Path, log_name_format: str, date_value: dt.date) -> Path:
    return log_dir / date_value.strftime(log_name_format)


def format_scratchpad_path(log_dir: Path, name: str) -> Path:
    return log_dir / "scratchpads" / f"{name}.md"


def safe_replace_year(date_value: dt.date, year: int) -> dt.date:
    try:
        return date_value.replace(year=year)
    except ValueError:
        return date_value.replace(year=year, month=2, day=28)


def event_display(event: AnnualEvent, today: dt.date) -> str:
    current_year_date = dt.date(today.year, event.month, event.day)
    if current_year_date >= today:
        delta = (current_year_date - today).days
        if delta == 0:
            detail = "(today)"
        elif delta == 1:
            detail = "(in 1 day)"
        else:
            detail = f"(in {delta} days)"
    else:
        delta = (today - current_year_date).days
        if delta == 1:
            detail = "(1 day ago)"
        else:
            detail = f"({delta} days ago)"
    return f"- {event.name} {event.day:02d}.{event.month:02d}. {detail}"


class CapsLogUI:
    def __init__(self, stdscr: "curses._CursesWindow", settings: Settings, repo_encrypted: bool, start_authenticated: bool):
        self.stdscr = stdscr
        self.settings = settings
        self.repo_encrypted = repo_encrypted
        self.authenticated = start_authenticated
        self.today = dt.date.today()
        self.display_year = self.today.year
        self.selected_date = self.today
        self.focus = "sections"
        self.entries: Dict[dt.date, LogEntry] = {}
        self.scratchpads: List[str] = []
        self.section_index = 0
        self.tag_index = 0
        self.selected_section: Optional[str] = None
        self.selected_tag: Optional[str] = None
        self.in_scratchpad = False
        self.scratch_index = 0
        self.modal: Optional[PromptModal] = None
        self.running = True
        self.error_after_exit: Optional[str] = None

        locale.setlocale(locale.LC_ALL, "")
        curses.curs_set(0)
        self.stdscr.keypad(True)
        curses.noecho()
        curses.cbreak()
        self._init_colors()

        self.reload_data()
        if self.repo_encrypted and not self.authenticated:
            self.modal = PromptModal(kind="password", title="Enter password for log files:", hidden=True)

    def _init_colors(self) -> None:
        if not curses.has_colors():
            return
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_RED, -1)
        curses.init_pair(2, curses.COLOR_BLUE, -1)
        curses.init_pair(3, curses.COLOR_GREEN, -1)
        curses.init_pair(4, curses.COLOR_YELLOW, -1)
        curses.init_pair(5, curses.COLOR_CYAN, -1)
        curses.init_pair(6, curses.COLOR_WHITE, -1)
        curses.init_pair(7, curses.COLOR_BLACK, curses.COLOR_WHITE)

    def color(self, pair: int, *attrs: int) -> int:
        value = curses.color_pair(pair)
        for attr in attrs:
            value |= attr
        return value

    def reload_data(self) -> None:
        if self.authenticated:
            self.entries = load_entries(self.settings.log_dir, self.settings.log_name_format, self.settings.first_line_section)
        else:
            self.entries = {}
        self.scratchpads = list_scratchpads(self.settings.log_dir)
        self._clamp_state()

    def _clamp_state(self) -> None:
        self.selected_date = safe_replace_year(self.selected_date, self.display_year)
        sections = self.section_items()
        if sections:
            self.section_index = max(0, min(self.section_index, len(sections) - 1))
            self.selected_section = sections[self.section_index][0]
        else:
            self.section_index = 0
            self.selected_section = None
        tags = self.tag_items()
        if tags:
            self.tag_index = max(0, min(self.tag_index, len(tags) - 1))
            self.selected_tag = tags[self.tag_index][0]
        else:
            self.tag_index = 0
            self.selected_tag = None
        scratch_count = len(self.scratchpads) + 1
        self.scratch_index = max(0, min(self.scratch_index, max(0, scratch_count - 1)))

    def run(self) -> int:
        while self.running:
            self.draw()
            key = self.stdscr.get_wch()
            self.handle_key(key)
        if self.error_after_exit:
            raise CapsLogError(self.error_after_exit)
        return 0

    def yearly_entries(self) -> Dict[dt.date, LogEntry]:
        return {date_value: entry for date_value, entry in self.entries.items() if date_value.year == self.display_year}

    def year_count(self) -> int:
        return len(self.yearly_entries())

    def section_counter(self) -> Counter[str]:
        counter: Counter[str] = Counter()
        for entry in self.yearly_entries().values():
            for section in dict.fromkeys(entry.section_names):
                counter[section] += 1
        return counter

    def tag_counter(self, section_filter: Optional[str]) -> Counter[str]:
        counter: Counter[str] = Counter()
        for entry in self.yearly_entries().values():
            seen: set[str] = set()
            for section_name, tag_name in entry.tags:
                if section_filter and section_name != section_filter:
                    continue
                if tag_name in seen:
                    continue
                seen.add(tag_name)
                counter[tag_name] += 1
        return counter

    def section_items(self) -> List[Tuple[Optional[str], Optional[int], str]]:
        if not self.authenticated:
            return []
        counter = self.section_counter()
        items: List[Tuple[Optional[str], Optional[int], str]] = [(None, None, "<select none>")]
        keys = list(counter.keys())
        keys.sort(key=lambda item: (item != ROOT_SECTION, -counter[item], item))
        for key in keys:
            items.append((key, counter[key], key))
        return items

    def tag_items(self) -> List[Tuple[Optional[str], Optional[int], str]]:
        if not self.authenticated:
            return []
        counter = self.tag_counter(self.selected_section)
        items: List[Tuple[Optional[str], Optional[int], str]] = [(None, None, "<select none>")]
        keys = sorted(counter.keys(), key=lambda item: (-counter[item], item))
        for key in keys:
            items.append((key, counter[key], key))
        return items

    def entry_matches_filter(self, entry: LogEntry) -> bool:
        if self.selected_section and self.selected_section not in entry.section_names:
            return False
        if self.selected_tag:
            if self.selected_section:
                return any(section == self.selected_section and tag == self.selected_tag for section, tag in entry.tags)
            return any(tag == self.selected_tag for _, tag in entry.tags)
        return True

    def event_dates(self) -> set[dt.date]:
        dates: set[dt.date] = set()
        for event in self.settings.annual_events:
            try:
                dates.add(dt.date(self.display_year, event.month, event.day))
            except ValueError:
                continue
        return dates

    def preview_title(self) -> str:
        if self.repo_encrypted and not self.authenticated:
            return "log preview"
        return f"log preview for {self.selected_date.strftime('%d. %m. %y. ')}"

    def preview_lines(self) -> List[Tuple[str, int]]:
        if self.repo_encrypted and not self.authenticated:
            return [("", 0)]
        entry = self.entries.get(self.selected_date)
        if entry is None:
            return [("", 0)]
        lines: List[Tuple[str, int]] = []
        for raw_line in entry.content.splitlines() or [""]:
            attr = 0
            if raw_line.startswith("# "):
                attr = self.color(4, curses.A_BOLD)
            elif raw_line.startswith("* "):
                attr = self.color(2)
            elif raw_line.startswith("> "):
                attr = self.color(5)
            lines.append((raw_line, attr))
        return lines

    def event_lines(self) -> List[str]:
        if not self.settings.annual_events:
            return []
        today = self.today
        lines: List[str] = []
        grouped: Dict[str, List[AnnualEvent]] = defaultdict(list)
        for event in self.settings.annual_events:
            grouped[event.group].append(event)
        for group in sorted(grouped.keys()):
            lines.append(group)
            for event in grouped[group]:
                lines.append(" " + event_display(event, today))
        return lines

    def open_editor(self, path: Path) -> None:
        editor = os.environ.get("EDITOR", "vi").strip() or "vi"
        command = shlex.split(editor) + [str(path)]
        curses.def_prog_mode()
        curses.endwin()
        try:
            subprocess.run(command, check=False)
        finally:
            curses.reset_prog_mode()
            curses.curs_set(0)
            self.stdscr.keypad(True)
            self.stdscr.refresh()
        self.reload_data()

