    settings.log_dir.mkdir(parents=True, exist_ok=True)

    def wrapped(stdscr: "curses._CursesWindow") -> int:
        app = CapsLogUI(stdscr, settings, repo_encrypted=repo_encrypted, start_authenticated=authenticated)
        return app.run()

    return curses.wrapper(wrapped)


