    try:
        parsed = parse_args(argv)
        if parsed.help:
            sys.stdout.write(
                HELP_TEMPLATE.format(version=VERSION, config_path=str(default_config_path())) + ("\n" if not HELP_TEMPLATE.endswith("\n") else "")
            )
            return 0

        settings = merge_settings(parsed)

        if settings.encrypt:
            return apply_encrypt(settings)
        if settings.decrypt:
            return apply_decrypt(settings)

        encrypted = marker_path(settings.log_dir).exists()
        if settings.password and not encrypted:
            raise CapsLogError("Password provided for a non encrypted repository!")
        if encrypted and settings.password and not validate_password(settings.log_dir, settings.password):
            raise CapsLogError("Invalid password provided!")

        authenticated = not encrypted or bool(settings.password)
        return run_tui(settings, repo_encrypted=encrypted, authenticated=authenticated)
    except KeyboardInterrupt:
        return 0
    except CapsLogError as exc:
        sys.stderr.write(format_error(str(exc)))
        return 1


