  ivs := []deriv{{"zero", func(string) []byte { return make([]byte,16)}},{"z16",zpad(16)},{"r16",repeat(16)},{"md5",truncHash(md5h,16)},{"sha1_16",truncHash(sha1h,16)},{"sha256_16",truncHash(sha256h,16)},{"sha512_16",truncHash(sha512h,16)}}
  for _,k := range keys {
    // ECB
    {
      var outs [][]byte; ok:=true
      for _,s := range samples {
        key:=k.fn(s.pwd); if key==nil{ok=false;break}
        block, err := aes.NewCipher(key); if err!=nil{ok=false;break}
        data,_ := hex.DecodeString(s.hex)
        out:=make([]byte,16)
        block.Decrypt(out,data[:16])
        outs=append(outs,out)
      }
      if ok && same(outs){fmt.Printf("MATCH key=%s mode=ECB16 plain=%x\n", k.name, outs[0])}
    }
    for _,ivd := range ivs {
      var outs [][]byte; ok:=true
      for _,s := range samples {
        key:=k.fn(s.pwd); iv:=ivd.fn(s.pwd); if key==nil||iv==nil{ok=false;break}
        block, err := aes.NewCipher(key); if err!=nil{ok=false;break}
        data,_ := hex.DecodeString(s.hex)
        out:=make([]byte,16)
        cipher.NewCBCDecrypter(block,iv).CryptBlocks(out,data[:16])
        outs=append(outs,out)
      }
      if ok && same(outs){fmt.Printf("MATCH key=%s iv=%s mode=CBC16 plain=%x\n", k.name, ivd.name, outs[0])}
    }
  }
}
